import React, { useState, useEffect } from 'react';
import { createRoot } from 'react-dom/client';
import { GoogleGenAI } from "@google/genai";
import { 
  Search, 
  Leaf, 
  AlertCircle, 
  CheckCircle2, 
  Info, 
  ExternalLink, 
  Loader2, 
  ArrowRight,
  ShieldCheck,
  Zap
} from 'lucide-react';

// --- Types ---
interface Ingredient {
  name: string;
  quantity: string;
  status: 'healthy' | 'harmful' | 'neutral';
  description: string;
}

interface AnalysisResult {
  productName: string;
  summary: string;
  ingredients: Ingredient[];
  sources: { title: string; uri: string }[];
}

// --- App Component ---
const FoodAnalyzer = () => {
  const [query, setQuery] = useState('');
  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState<AnalysisResult | null>(null);
  const [error, setError] = useState<string | null>(null);

  const analyzeFood = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!query.trim()) return;

    setLoading(true);
    setError(null);
    setResult(null);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

      const prompt = `
        Analyze the food product: "${query}".
        Provide the exact or estimated ingredients with their quantities (per serving or total if known).
        For each ingredient, classify it as "healthy", "harmful", or "neutral".
        Provide a brief explanation for the classification.
        Double-check these values against current food databases and manufacturer labels using Google Search.

        Return the response in a structured format like this:
        PRODUCT: [Name]
        SUMMARY: [Short overview of healthiness]

        INGREDIENTS_LIST:
        - [Ingredient Name] | [Quantity] | [Status: healthy/harmful/neutral] | [Reasoning]

        Ensure you are precise. If exact quantities aren't available, provide estimates based on common manufacturing standards.
      `;

      const response = await ai.models.generateContent({
        model: 'gemini-3-pro-preview',
        contents: prompt,
        config: {
          tools: [{ googleSearch: {} }],
        },
      });

      const text = response.text || "";
      const groundingChunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks || [];
      const sources = groundingChunks
        .filter((chunk: any) => chunk.web)
        .map((chunk: any) => ({
          title: chunk.web.title,
          uri: chunk.web.uri,
        }));

      // Basic parsing of the structured text response
      const lines = text.split('\n');
      let productName = query;
      let summary = "";
      const ingredients: Ingredient[] = [];

      let section = "";
      for (const line of lines) {
        if (line.startsWith("PRODUCT:")) productName = line.replace("PRODUCT:", "").trim();
        else if (line.startsWith("SUMMARY:")) summary = line.replace("SUMMARY:", "").trim();
        else if (line.startsWith("- ") && line.includes("|")) {
          const parts = line.substring(2).split('|').map(p => p.trim());
          if (parts.length >= 4) {
            ingredients.push({
              name: parts[0],
              quantity: parts[1],
              status: parts[2].toLowerCase() as any,
              description: parts[3]
            });
          }
        }
      }

      if (ingredients.length === 0) {
        throw new Error("Could not parse ingredient data. The AI might have returned an unexpected format.");
      }

      setResult({
        productName,
        summary,
        ingredients,
        sources
      });

    } catch (err: any) {
      console.error(err);
      setError(err.message || "An error occurred while analyzing the product.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-slate-50 text-slate-900 font-sans selection:bg-emerald-100">
      {/* Header */}
      <header className="bg-white border-b sticky top-0 z-10">
        <div className="max-w-5xl mx-auto px-4 h-16 flex items-center justify-between">
          <div className="flex items-center gap-2">
            <div className="bg-emerald-600 p-1.5 rounded-lg">
              <ShieldCheck className="w-6 h-6 text-white" />
            </div>
            <h1 className="text-xl font-bold tracking-tight text-slate-800">PurePlate <span className="text-emerald-600">AI</span></h1>
          </div>
