                  <h3 className="text-3xl font-bold text-slate-800">{result.productName}</h3>
                </div>
                <div className="flex items-center gap-2 bg-slate-50 px-4 py-2 rounded-xl border border-slate-100">
                  <CheckCircle2 className="w-5 h-5 text-emerald-500" />
                  <span className="text-sm font-medium text-slate-600 italic">AI Double-Checked</span>
                </div>
              </div>
              <p className="text-slate-600 leading-relaxed text-lg border-l-4 border-emerald-200 pl-6">
                {result.summary}
              </p>
            </div>

            {/* Ingredients Breakdown */}
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              {/* Healthy / Neutral */}
              <div className="space-y-4">
