} from 'lucide-react';

// --- Types ---
interface Ingredient {
  name: string;
  quantity: string;
  status: 'healthy' | 'harmful' | 'neutral';
  description: string;
}

interface AnalysisResult {
  productName: string;
  summary: string;
  ingredients: Ingredient[];
  sources: { title: string; uri: string }[];
}

// --- App Component ---
const FoodAnalyzer = () => {
  const [query, setQuery] = useState('');
  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState<AnalysisResult | null>(null);
  const [error, setError] = useState<string | null>(null);

  const analyzeFood = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!query.trim()) return;

    setLoading(true);
    setError(null);
    setResult(null);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

      const prompt = `
        Analyze the food product: "${query}".
        Find the ingredients and their quantities (per standard serving or total).
        For each ingredient, classify it as "healthy", "harmful", or "neutral".
        Provide a brief explanation for why it's healthy or harmful.
        Double-check these values using Google Search for accuracy.

        CRITICAL: Format the response EXACTLY as follows:
        PRODUCT: [Product Name]
        SUMMARY: [Short overview]
        LIST_START
        [Ingredient Name] | [Quantity] | [Status: healthy/harmful/neutral] | [Reason]
        [Next Ingredient Name] | [Quantity] | [Status: healthy/harmful/neutral] | [Reason]
        ... and so on ...
        LIST_END
      `;

      const response = await ai.models.generateContent({
        model: 'gemini-3-pro-preview',
        contents: prompt,
        config: {
          tools: [{ googleSearch: {} }],
        },
      });

      const text = response.text || "";
      if (!text) throw new Error("The AI returned an empty response.");

      // Parse grounding sources
      const groundingChunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks || [];
      const sources = groundingChunks
        .filter((chunk: any) => chunk.web)
        .map((chunk: any) => ({
          title: chunk.web.title,
          uri: chunk.web.uri,
        }));

      // Robust Parsing
      let productName = query;
      let summary = "Detailed breakdown below.";
      const ingredients: Ingredient[] = [];

      // Extract Product Name
      const productMatch = text.match(/PRODUCT:\s*(.*)/i);
      if (productMatch) productName = productMatch[1].trim();

      // Extract Summary
      const summaryMatch = text.match(/SUMMARY:\s*([\s\S]*?)(?=LIST_START|$)/i);
      if (summaryMatch) summary = summaryMatch[1].trim();

      // Extract List section
      const listSectionMatch = text.match(/LIST_START([\s\S]*?)LIST_END/i);
      const contentToParse = listSectionMatch ? listSectionMatch[1] : text;

      const lines = contentToParse.split('\n').map(l => l.trim()).filter(l => l.includes('|'));

      for (const line of lines) {
        // Remove leading dashes, asterisks, or numbers
        const cleanLine = line.replace(/^[-*•\d.]\s*/, '');
        const parts = cleanLine.split('|').map(p => p.trim());

        if (parts.length >= 3) {
          const statusRaw = parts[2]?.toLowerCase() || 'neutral';
          let status: 'healthy' | 'harmful' | 'neutral' = 'neutral';

          if (statusRaw.includes('harmful') || statusRaw.includes('unhealthy') || statusRaw.includes('bad')) {
            status = 'harmful';
          } else if (statusRaw.includes('healthy') || statusRaw.includes('good') || statusRaw.includes('fine')) {
            status = 'healthy';
          }

          ingredients.push({
            name: parts[0],
            quantity: parts[1] || 'Unknown',
            status: status,
            description: parts[3] || 'No further details available.'
          });
        }
      }

      if (ingredients.length === 0) {
        console.debug("Raw AI Text:", text); // Helpful for developers
        throw new Error("Could not find a structured list of ingredients in the response. Please try a more specific product name.");
      }

      setResult({
        productName,
        summary,
        ingredients,
        sources
      });

    } catch (err: any) {
      console.error(err);
      setError(err.message || "An error occurred while analyzing the product.");
    } finally {
      setLoading(false);
    }
  };

