    e.preventDefault();
    if (!query.trim()) return;

    setLoading(true);
    setError(null);
    setResult(null);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

      const prompt = `
        Analyze the Indian food product: "${query}". 
        Focus specifically on products available in the Indian market (e.g., brands like Amul, Haldiram's, Maggi India, Britannia, Parle, etc.).

        Tasks:
        1. Identify the ingredients and their quantities based on Indian FSSAI labeling standards.
        2. Classify each as "healthy", "harmful", or "neutral" based on common health impacts (e.g., high maida, palm oil, or excessive sugar in Indian snacks).
        3. Mention any specific FSSAI regulations or recent health controversies related to this product in India if they exist.
        4. Use Google Search to verify the current packaging/ingredient list for the Indian version of this product.

        CRITICAL: Format the response EXACTLY as follows:
        PRODUCT: [Product Name]
        SUMMARY: [Short overview focusing on Indian health context]
        FSSAI_NOTICE: [Any specific regulatory note or "None" if not applicable]
        LIST_START
        [Ingredient Name] | [Quantity] | [Status: healthy/harmful/neutral] | [Reason in Indian context]
        [Next Ingredient Name] | [Quantity] | [Status: healthy/harmful/neutral] | [Reason]
        ...
        LIST_END
      `;

      const response = await ai.models.generateContent({
        model: 'gemini-3-pro-preview',
        contents: prompt,
        config: {
          tools: [{ googleSearch: {} }],
        },
      });

      const text = response.text || "";
      if (!text) throw new Error("The AI returned an empty response.");

      // Parse grounding sources
      const groundingChunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks || [];
      const sources = groundingChunks
        .filter((chunk: any) => chunk.web)
        .map((chunk: any) => ({
          title: chunk.web.title,
          uri: chunk.web.uri,
