    return 'text-rose-600 border-rose-100 bg-rose-50';
  };

  const getScoreBg = (score: number) => {
    if (score >= 70) return 'bg-emerald-600';
    if (score >= 40) return 'bg-orange-600';
    return 'bg-rose-600';
  };

  return (
