                    <div className="w-32 h-2 bg-slate-100 rounded-full overflow-hidden">
                      <div className={`h-full transition-all duration-1000 ${getScoreBg(result.healthScore || 50)}`} style={{ width: `${result.healthScore}%` }}></div>
